{"note": "EL-on-last-X-MB and fractional EL sweeps, with plain vs EF loads, at 1024-8192 tokens", "script": "import torch, b200probe as bp
src = r'''
template<int LD>
__device__ void body(const float* __restrict__ q, const float* __restrict__ k, const float* __restrict__ wq, const float* __restrict__ wk,
     float* __restrict__ qo, float* __restrict__ ko, int n_tiles, float eps, int el_from, int early, float frac) {
