  const float* pw = w + head*128 + c;
  asm volatile("ld.global.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];" : "=f"(wv[0]),"=f"(wv[1]),"=f"(wv[2]),"=f"(wv[3]),"=f"(wv[4]),"=f"(wv[5]),"=f"(wv[6]),"=f"(wv[7]) : "l"(pw));
  float s=0.f; for(int i=0;i<8;i++) s=fmaf(v[i],v[i],s);
  s+=__shfl_xor_sync(0xffffffffu,s,8); s+=__shfl_xor_sync(0xffffffffu,s,4); s+=__shfl_xor_sync(0xffffffffu,s,2); s+=__shfl_xor_sync(0xffffffffu,s,1);
  float inv = rsqrtf(s*(1.f/128.f)+eps); for(int i=0;i<8;i++) v[i]=v[i]*inv*wv[i];
  float* py = y + row*128 + c; unsigned long long ps;
  if (bid >= el_from) asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, %1;":"=l"(ps):"f"(frac));
  else if (early==1) asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;":"=l"(ps));
