}
extern "C" __global__ void __launch_bounds__(256,8) k0(const float* q,const float* k,const float* wq,const float* wk,float* qo,float* ko,int nt,float e,int a,int b,float f){ body<0>(q,k,wq,wk,qo,ko,nt,e,a,b,f);}
extern "C" __global__ void __launch_bounds__(256,8) k1(const float* q,const float* k,const float* wq,const float* wk,float* qo,float* ko,int nt,float e,int a,int b,float f){ body<1>(q,k,wq,wk,qo,ko,nt,e,a,b,f);}
