                          float* qo, float* ko, long long n_tiles, int ld_ef, float eps, cudaStream_t stream) {
    const dim3 grid((unsigned)(2 * n_tiles));
    if (ld_ef)
        qk_rms_kernel<true><<<grid, THREADS, 0, stream>>>(q, k, wq, wk, qo, ko, (int)n_tiles, eps);
    else
        qk_rms_kernel<false><<<grid, THREADS, 0, stream>>>(q, k, wq, wk, qo, ko, (int)n_tiles, eps);
    return (int)cudaGetLastError();
}
